from pathlib import Path
import shutil

CARPETA = Path("descargas_demo")  # en tu PC: Path.home() / "Downloads"
CARPETA.mkdir(exist_ok=True)
for nombre in ("factura.pdf", "foto.jpg", "notas.txt"):
    (CARPETA / nombre).touch()  # archivos de ejemplo

DESTINOS = {".pdf": "Documentos", ".jpg": "Imagenes", ".png": "Imagenes"}
SIMULAR = True  # cambia a False solo cuando la simulación sea correcta

for archivo in CARPETA.iterdir():
    subcarpeta = DESTINOS.get(archivo.suffix.lower())
    if archivo.is_file() and subcarpeta:
        destino = CARPETA / subcarpeta / archivo.name
        print(f"{archivo.name} -> {subcarpeta}/")
        if not SIMULAR and not destino.exists():
            destino.parent.mkdir(exist_ok=True)
            shutil.move(archivo, destino)

