# pip install flask
from flask import Flask, abort

app = Flask(__name__)
TAREAS = {1: {"id": 1, "titulo": "Estudiar Python", "hecha": False}}


@app.get("/api/tareas")
def listar_tareas():
    return list(TAREAS.values())


@app.get("/api/tareas/<int:tarea_id>")
def obtener_tarea(tarea_id: int):
    if tarea_id not in TAREAS:
        abort(404)
    return TAREAS[tarea_id]


if __name__ == "__main__":
    app.run(debug=True)  # http://127.0.0.1:5000/api/tareas

